function bezierPoint(p0,p1,p2,t) {
  const u=1-t;
  return {x:u*u*p0.x+2*u*t*p1.x+t*t*p2.x,
    y:u*u*p0.y+2*u*t*p1.y+t*t*p2.y};
}
const path=[];
for(let i=0;i<=samples;i++) path.push(bezierPoint(P0,P1,P2,i/samples));
